import React, { useEffect, useRef, useState } from 'react';
import './App.css';

const SAMPLE_RESPONSE = "Sure! Here's a short streaming reply. It arrives token by token so the UI feels responsive.";

// failAfter ends the stream early and reports it through onFail.
function startFakeStream(text, onChunk, onDone, onFail, failAfter = Infinity) {
  const tokens = text.split(' ');
  let i = 0;
  const id = window.setInterval(() => {
    const chunk = tokens[i] + (i < tokens.length - 1 ? ' ' : '');
    onChunk(chunk);
    i += 1;
    if (i >= failAfter) {
      window.clearInterval(id);
      onFail();
      return;
    }
    if (i >= tokens.length) {
      window.clearInterval(id);
      onDone();
    }
  }, 120);
  return () => window.clearInterval(id);
}

export default function App() {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [isStreaming, setIsStreaming] = useState(false);
  const [chatStatus, setChatStatus] = useState('');

  const cancelRef = useRef(null);
  const streamIdRef = useRef(null);
  const idRef = useRef(0);
  const inputRef = useRef(null);

  const nextId = () => `m_${idRef.current++}`;

  useEffect(() => {
    return () => {
      if (cancelRef.current) cancelRef.current();
    };
  }, []);

  const updateMessage = (id, change) => {
    setMessages((prev) => prev.map((message) => (
      message.id === id ? { ...message, ...change(message) } : message
    )));
  };

  // Every way a stream can end goes through here.
  const endStream = (id, status, announcement) => {
    cancelRef.current = null;
    streamIdRef.current = null;
    setIsStreaming(false);
    setChatStatus(announcement);
    updateMessage(id, () => ({ status }));
  };

  const runStream = (id, failAfter) => {
    streamIdRef.current = id;
    setIsStreaming(true);
    setChatStatus('Assistant is responding');
    cancelRef.current = startFakeStream(
      SAMPLE_RESPONSE,
      (chunk) => updateMessage(id, (message) => ({ text: message.text + chunk })),
      () => endStream(id, 'done', 'Response complete'),
      () => endStream(id, 'failed', 'Response failed'),
      failAfter
    );
  };

  const stopStream = () => {
    if (cancelRef.current) cancelRef.current();
    if (streamIdRef.current) endStream(streamIdRef.current, 'stopped', 'Response stopped');
    // The focused Stop button is gone now.
    inputRef.current?.focus();
  };

  const retry = (id) => {
    updateMessage(id, () => ({ text: '', status: 'streaming' }));
    runStream(id);
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    const trimmed = input.trim();
    if (!trimmed || isStreaming) return;

    const userId = nextId();
    const assistantId = nextId();

    setMessages((prev) => [
      ...prev,
      { id: userId, role: 'user', text: trimmed, status: 'done' },
      { id: assistantId, role: 'assistant', text: '', status: 'streaming' }
    ]);

    setInput('');
    runStream(assistantId, /\bfail\b/i.test(trimmed) ? 3 : undefined);
  };

  return (
    <main className="chat-shell">
      <section className="chat-card">
        <header className="chat-header">
          <h1>Chat UI</h1>
          <p className="subtitle">Streaming assistant responses.</p>
        </header>

        <ul className="chat-list">
          {messages.map((message) => (
            <li
              key={message.id}
              className={`message message--${message.role}`}
              aria-busy={message.role === 'assistant' ? message.status === 'streaming' : undefined}
            >
              <div className="message-role">{message.role === 'user' ? 'You' : 'Assistant'}</div>
              <div className="message-bubble">
                {message.text || (message.status === 'streaming' ? '...' : '')}
              </div>
              {message.status === 'stopped' && <div className="message-status">Stopped</div>}
              {message.status === 'failed' && (
                <div className="message-status">
                  Response failed
                  <button
                    type="button"
                    className="retry-response"
                    disabled={isStreaming}
                    onClick={() => retry(message.id)}
                  >
                    Retry
                  </button>
                </div>
              )}
            </li>
          ))}
          {messages.length === 0 && <li className="empty">Start a conversation.</li>}
        </ul>

        <p className="chat-status" aria-live="polite">{chatStatus}</p>

        <form className="chat-input" onSubmit={handleSubmit}>
          <input
            ref={inputRef}
            type="text"
            value={input}
            onChange={(event) => setInput(event.target.value)}
            placeholder="Ask something..."
          />
          <button type="submit" disabled={isStreaming || !input.trim()}>
            Send
          </button>
          {isStreaming && (
            <button type="button" className="ghost" onClick={stopStream}>
              Stop
            </button>
          )}
        </form>
      </section>
    </main>
  );
}

