:root {
  color-scheme: dark;
}

html,body {
  margin: 0;
  height: 100%;
  background: #09090b;
}

body {
  font-family: system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}

.chat-shell {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #09090b;
  color: #e5e7eb;
}

.chat-card {
  width: 100%;
  max-width: 720px;
  min-height: 560px;
  background: #0f172a;
  border: 1px solid #263244;
  border-radius: 16px;
  display: grid;
  grid-template-rows: auto 1fr auto;
  overflow: hidden;
}

.chat-header {
  padding: 18px 20px;
  border-bottom: 1px solid #263244;
}

.chat-header h1 {
  margin: 0;
  font-size: 20px;
  font-weight: 850;
}

.subtitle {
  margin: 4px 0 0;
  color: #94a3b8;
  font-size: 13px;
}

.chat-list {
  list-style: none;
  margin: 0;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  overflow: auto;
}

.empty {
  margin: auto;
  color: #64748b;
  font-size: 14px;
}

.message {
  display: grid;
  gap: 4px;
  max-width: 80%;
}

.message--user {
  align-self: flex-end;
  text-align: right;
}

.message--assistant {
  align-self: flex-start;
}

.message-role {
  font-size: 11px;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: .04em;
}

.message-bubble {
  border-radius: 14px;
  padding: 10px 12px;
  background: #172033;
  border: 1px solid #263244;
  line-height: 1.45;
}

.message--user .message-bubble {
  background: #a3e635;
  color: #111827;
  border-color: #a3e635;
}

.chat-input {
  display: flex;
  gap: 8px;
  padding: 14px;
  border-top: 1px solid #263244;
  background: #0b1220;
}

.chat-input input {
  flex: 1;
  min-width: 0;
  border: 1px solid #334155;
  background: #111827;
  color: #e5e7eb;
  border-radius: 12px;
  padding: 10px 12px;
}

.chat-input button {
  border: 0;
  border-radius: 12px;
  padding: 10px 14px;
  background: #a3e635;
  color: #111827;
  font-weight: 800;
  cursor: pointer;
}

.chat-input button:disabled {
  opacity: .45;
  cursor: not-allowed;
}

.chat-input .ghost {
  background: transparent;
  color: #e5e7eb;
  border: 1px solid #475569;
}

@media (max-width:640px) {
  .chat-shell {
    padding: 12px;
  }

  .chat-card {
    min-height: 520px;
  }

  .chat-input {
    flex-wrap: wrap;
  }

  .chat-input input {
    flex-basis: 100%;
  }

  .message {
    max-width: 92%;
  }
}

.message-status {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: #94a3b8;
}

.retry-response {
  border: 1px solid #263244;
  border-radius: 8px;
  background: transparent;
  color: #e5e7eb;
  padding: 4px 10px;
  font-size: 12px;
  cursor: pointer;
}

.retry-response:disabled {
  opacity: .5;
  cursor: not-allowed;
}

.chat-status {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
